"""Emission compliance tests for project_scaffold (auto-generated by pact)."""

from project_scaffold.project_scaffold import ProjectScaffold


class TestEmissionCompliance:
    """Verify project_scaffold emits structured events correctly."""

    def _make_handler(self):
        events = []
        return events, lambda event: events.append(event)

    def test_initialize_project_emits_events(self):
        """Method initialize_project emits invoked and completed events."""
        events, handler = self._make_handler()
        obj = ProjectScaffold(event_handler=handler)
        try:
            obj.initialize_project()
        except (TypeError, Exception):
            pass
        invoked = [e for e in events if e.get("event") == "invoked"]
        completed = [e for e in events if e.get("event") in ("completed", "error")]
        assert len(invoked) >= 1, 'No invoked event for initialize_project'
        assert len(completed) >= 1, 'No completed/error event for initialize_project'
        assert invoked[0].get("pact_key") == "PACT:project_scaffold:initialize_project"
        assert isinstance(invoked[0].get("input_classification"), list)

