    def test_pact_key_format(self):
        """All emitted events have correctly formatted PACT keys."""
        events, handler = self._make_handler()
        obj = ProjectScaffold(event_handler=handler)
        try:
            obj.initialize_project()
        except (TypeError, Exception):
            pass
        try:
            obj.install_dependencies()
        except (TypeError, Exception):
            pass
        try:
            obj.configure_vite()
        except (TypeError, Exception):
            pass
        try:
            obj.configure_tailwind()
        except (TypeError, Exception):
            pass
        try:
            obj.configure_typescript()
        except (TypeError, Exception):
            pass
        try:
            obj.configure_entry_points()
        except (TypeError, Exception):
            pass
        try:
            obj.configure_package_json_scripts()
        except (TypeError, Exception):
            pass
        try:
            obj.validate_scaffold()
        except (TypeError, Exception):
            pass
        try:
            obj.get_dependency_manifest()
        except (TypeError, Exception):
            pass
        try:
            obj.get_style_tokens()
        except (TypeError, Exception):
            pass
        for event in events:
            key = event.get("pact_key", "")
            assert key.startswith("PACT:project_scaffold:"), f"Bad pact_key: {key}"

